option.value:
import type { Metadata } from "next";

import { Section } from "@/components/section";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { galleryItems } from "@/lib/site-content";

export const metadata: Metadata = {
  title: "Gallery | Peppermint Audio",
  description: "Sample PA setups for private events and weddings in Melbourne.",
};

export default function GalleryPage() {
  return (
    <Section
      eyebrow="Social Proof"
      title="Gallery"
      description="Real-world setup examples. Replace these placeholders with your own event photos."
    >
      <div className="grid gap-4 md:grid-cols-3">
        {galleryItems.map((item) => (
          <Card key={item.title} className="border">
            <div className="h-40 rounded-t-xl bg-gradient-to-br from-muted to-muted/40" />
            <CardHeader>
              <Badge variant="outline" className="w-fit">Recent event</Badge>
              <CardTitle className="text-lg">{item.title}</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-muted-foreground">{item.description}</p>
            </CardContent>
          </Card>
        ))}
      </div>
    </Section>
  );
}

import type { Metadata } from "next";
import Image from "next/image";

import { Section } from "@/components/section";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { galleryItems } from "@/lib/site-content";

export const metadata: Metadata = {
  title: "Gallery | Peppermint Audio",
  description: "Sample PA setups for private events and weddings in Melbourne.",
};

export default function GalleryPage() {
  return (
    <Section
      eyebrow="Social Proof"
      title="Gallery"
      description="Real-world setup examples from Melbourne events."
    >
      <div className="grid gap-4 md:grid-cols-3">
        {galleryItems.map((item) => (
          <Card key={item.title} className="overflow-hidden border">
            <div className="relative h-48">
              <Image
                src={item.image}
                alt={item.title}
                fill
                sizes="(max-width: 768px) 100vw, 33vw"
                className="object-cover"
              />
            </div>
            <CardHeader>
              <Badge variant="outline" className="w-fit">Recent event</Badge>
              <CardTitle className="text-lg">{item.title}</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-muted-foreground">{item.description}</p>
            </CardContent>
          </Card>
        ))}
      </div>
    </Section>
  );
}

import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import type { PackageTier } from "@/lib/site-content";

type PackageCardProps = {
  pkg: PackageTier;
};

export function PackageCard({ pkg }: PackageCardProps) {
  return (
    <Card className="h-full justify-between border">
      <CardHeader>
        <CardTitle>{pkg.name}</CardTitle>
        <CardAction>{pkg.notes ? <Badge>{pkg.notes}</Badge> : null}</CardAction>
        <CardDescription>{pkg.bestFor}</CardDescription>
        <p className="mt-2 text-3xl font-semibold tracking-tight">${pkg.nightlyPrice}/night</p>
      </CardHeader>
      <CardContent>
        <ul className="space-y-2 text-sm text-muted-foreground">
          {pkg.inclusions.map((item) => (
            <li key={item}>- {item}</li>
          ))}
        </ul>
      </CardContent>
      <CardFooter>
        <Button className="w-full" render={<Link href="/contact" />}>
          Enquire about this package
        </Button>
      </CardFooter>
    </Card>
  );
}

