export type PackageTier = {
  slug: string;
  name: string;
  nightlyPrice: number;
  bestFor: string;
  inclusions: string[];
  notes?: string;
};

export const business = {
  name: "Peppermint Audio",
  serviceArea: "Melbourne",
  pickupSuburb: "Abbotsford",
  pickupPostcode: "3067",
  phone: "0400 000 000",
  email: "hello@peppermintaudio.com.au",
  heroHeading: "PA speaker hire for Melbourne events",
  heroSubheading:
    "Reliable speaker, microphone, mixer, and cable packages for parties, weddings, and private functions.",
};

